        var toolbar = Wrap("Imagine.Toolbar", 6); foreach (var button in new[] { Action("Import", "Import", "plus"), Action("Save", "Save", "file"), Action("Export", "Export", "archive"), Action("Undo", "Undo", "chevron-left"), Action("Redo", "Redo", "chevron-right"), Action("AddRectangle", "Rectangle", "window"), Action("Duplicate", "Duplicate", "plus"), Action("Delete", "Delete", "delete"), Action("Decompose", "Semantic parts", "sparkles"), Action("Fit", "Fit canvas", "search"), Action("InspectVision", "Inspect in Vision", "vision") }) toolbar.Add(button); TextInput = new Input { Name = "Imagine.TextInput", Placeholder = "Text to add", SubmitOnEnter = true }; TextInput.SetValue(HavenProperties.MinWidth, HavenLength.Px(160)); toolbar.Add(TextInput); toolbar.Add(Action("AddText", "Add text", "edit")); Root.Add(toolbar);
