        var right = Vertical("Imagine.Right", 8); right.SetValue(HavenProperties.Column, 2); right.SetValue(HavenProperties.Overflow, HavenOverflow.Scroll); Body.Add(right); ProjectTitle = Heading("Untitled Imagine Project"); right.Add(ProjectTitle); Selection = Muted("Imagine.Selection", "Nothing selected."); right.Add(Selection); right.Add(Heading("Semantic components")); Components = Runtime("Imagine.Components"); right.Add(Components); ComponentsEmpty = Muted("Imagine.ComponentsEmpty", "No semantic decomposition yet. Select an image and choose Semantic parts."); right.Add(ComponentsEmpty); Status = Muted("Imagine.Status", "Loading…"); right.Add(Status);
        Assistant = _prefabs.Create("Chatbox", "Imagine-Chatbox"); AssistantInput = Assistant.GetComponent<Input>("Instruction"); AssistantInput.Placeholder = "Ask Haven to edit the selected object"; AssistantInput.Multiline = true; AssistantInput.SubmitOnEnter = true; Assistant.GetComponent<HavenButton>("AddMenu").SetValue(HavenProperties.Visibility, HavenVisibility.Collapsed); AssistantSend = Assistant.GetComponent<HavenButton>("Send"); AssistantSend.Accessibility.AccessibleName = "Apply AI structural edit to selection"; Root.Add(Assistant);
        _dynamic = new DynamicUI(Root, HavenDynamicUITemplateCatalog.FromAssembly(typeof(ImagineScene).Assembly), _prefabs); Wire("Import", () => ImportRequested?.Invoke(this, EventArgs.Empty)); Wire("Save", () => SaveRequested?.Invoke(this, EventArgs.Empty)); Wire("Export", () => ExportRequested?.Invoke(this, EventArgs.Empty)); Wire("Undo", () => UndoRequested?.Invoke(this, EventArgs.Empty)); Wire("Redo", () => RedoRequested?.Invoke(this, EventArgs.Empty)); Wire("AddRectangle", () => AddRectangleRequested?.Invoke(this, EventArgs.Empty)); Wire("AddText", () => AddTextRequested?.Invoke(this, EventArgs.Empty)); Wire("Duplicate", () => DuplicateRequested?.Invoke(this, EventArgs.Empty)); Wire("Delete", () => DeleteRequested?.Invoke(this, EventArgs.Empty)); Wire("Decompose", () => DecomposeRequested?.Invoke(this, EventArgs.Empty)); Wire("Fit", () => FitRequested?.Invoke(this, EventArgs.Empty)); Wire("InspectVision", () => InspectVisionRequested?.Invoke(this, EventArgs.Empty)); AssistantSend.Invoked += (_, _) => SubmitAssistant(); SetViewportWidth(1280);
    }
    public HavenPage Root { get; } public HavenContainer Body { get; } public DynamicUIRuntime RecentProjects { get; } public DynamicUIRuntime Assets { get; } public DynamicUIRuntime Components { get; } public ImagineCanvasElement Canvas { get; } public HavenText ProjectTitle { get; } public HavenText Selection { get; } public HavenText TrackSummary { get; } public HavenText ComponentsEmpty { get; } public HavenText Status { get; } public Prefab Assistant { get; } public Input AssistantInput { get; } public HavenButton AssistantSend { get; } public Input TextInput { get; }
