        foreach (var item in recent.Take(20)) { var row = _dynamic.CreateItem("ImagineProjectRow", RecentProjects.Name!, "project-" + item.Id.ToString("N"), new Dictionary<string, object?> { ["TITLE"] = item.Name, ["DETAIL"] = item.UpdatedAt.LocalDateTime.ToString("d MMM HH:mm") }); row.GetComponent<HavenButton>("Open").Invoked += (_, _) => ProjectRequested?.Invoke(item); }
