        foreach (var component in project.SemanticComponents.OrderBy(item => item.Order)) { var depth = Depth(component, project.SemanticComponents); var row = _dynamic.CreateItem("ImagineComponentRow", Components.Name!, "component-" + component.Id.ToString("N"), new Dictionary<string, object?> { ["TITLE"] = new string('·', depth) + (depth == 0 ? string.Empty : " ") + component.Label, ["DETAIL"] = component.Confidence is double confidence ? $"{component.Type} · {confidence:P0}" : component.Type }); row.GetComponent<HavenButton>("Open").Invoked += (_, _) => ComponentRequested?.Invoke(component); } ComponentsEmpty.SetValue(HavenProperties.Visibility, project.SemanticComponents.Length == 0 ? HavenVisibility.Visible : HavenVisibility.Collapsed);
    }
    public void SetStatus(string value) => Status.Content = value; public void SetUnavailable(string value) { Status.Content = value; RecentProjects.ClearItems(); Assets.ClearItems(); Components.ClearItems(); }
    public void SetViewportWidth(double width) { if (!double.IsFinite(width) || width <= 0) return; Body.Columns = width < 760 ? "1fr" : width < 1100 ? "220px 1fr" : "240px 1fr 300px"; foreach (var child in Body.Children) child.SetValue(HavenProperties.Visibility, HavenVisibility.Visible); if (width < 760) { Body.Children[0].SetValue(HavenProperties.Visibility, HavenVisibility.Collapsed); Body.Children[2].SetValue(HavenProperties.Visibility, HavenVisibility.Collapsed); Canvas.SetValue(HavenProperties.Column, 0); } else if (width < 1100) { Body.Children[2].SetValue(HavenProperties.Visibility, HavenVisibility.Collapsed); Canvas.SetValue(HavenProperties.Column, 1); } else Canvas.SetValue(HavenProperties.Column, 1); }
    private void SubmitAssistant() { var prompt = AssistantInput.Text.Trim(); if (!string.IsNullOrWhiteSpace(prompt)) AssistantRequested?.Invoke(prompt); }
    private static string SelectionLabel(ImagineProject project) { var selection = project.Selection; if (selection.Kind == ImagineSelectionKind.Object && selection.TargetId is Guid objectId && project.Objects.FirstOrDefault(item => item.Id == objectId) is { } obj) return $"Selected: {obj.Name} · x {obj.Transform.X:0} y {obj.Transform.Y:0} · {obj.Transform.Width:0}×{obj.Transform.Height:0} · {obj.Transform.RotationDegrees:0.#}°"; if (selection.Kind == ImagineSelectionKind.SemanticComponent && selection.TargetId is Guid componentId && project.SemanticComponents.FirstOrDefault(item => item.Id == componentId) is { } component) return $"Semantic selection: {component.Label} · {component.Type}"; if (selection.Kind == ImagineSelectionKind.Track) return "Audio/video track selected."; return "Nothing selected."; }
