internal sealed class ImagineCanvasElement : HavenElement, IHavenDrawCommandSource, IHavenPointerInputTarget, IHavenScrollInputTarget, IDisposable
{
    private enum Interaction { None, Move, Resize, Rotate, Pan } private ImagineProjectSession? _session; private Interaction _interaction; private ImagineEditableObject? _original; private ImagineTransform? _preview; private HavenPoint _pointerStart; private HavenPoint _offset; private double _zoom = 1; private bool _fitPending = true;
    public ImagineCanvasElement() { Accessibility.Role = HavenAccessibleRole.Image; Accessibility.Focusable = true; Accessibility.AccessibleName = "Imagine editable canvas"; SetValue(HavenProperties.Background, "SurfaceRaised"); SetValue(HavenProperties.BorderColor, "Border"); SetValue(HavenProperties.BorderWidth, HavenLength.Px(1)); SetValue(HavenProperties.Radius, HavenCornerRadius.Uniform(HavenLength.Px(16))); SetValue(HavenProperties.Clip, true); } public void SetSession(ImagineProjectSession session) { if (ReferenceEquals(_session, session)) return; if (_session is not null) _session.Changed -= OnSessionChanged; _session = session; _session.Changed += OnSessionChanged; _fitPending = true; Invalidate(); } public void Fit() { _fitPending = true; Invalidate(); } public void InvalidateCanvas() => Invalidate();
    public bool PointerPressed(HavenPointerInput input) { if (_session is null) return false; EnsureFit(); _pointerStart = input.LocalPosition; var selected = SelectedObject(); if (selected is not null && HandleHit(selected.Transform, input.LocalPosition, true)) { _interaction = Interaction.Rotate; _original = selected; _preview = selected.Transform; return true; } if (selected is not null && HandleHit(selected.Transform, input.LocalPosition, false)) { _interaction = Interaction.Resize; _original = selected; _preview = selected.Transform; return true; } var board = ToBoard(input.LocalPosition); var hit = _session.Project.Objects.Where(item => item.IsVisible).OrderByDescending(item => item.ZIndex).FirstOrDefault(item => Contains(item.Transform, board)); if (hit is not null) { _session.SelectObject(hit.Id); _interaction = Interaction.Move; _original = hit; _preview = hit.Transform; return true; } _session.ClearSelection(); _interaction = Interaction.Pan; return true; }
    public bool PointerMoved(HavenPointerInput input) { if (_session is null) return false; var delta = new HavenPoint((input.LocalPosition.X - _pointerStart.X) / Math.Max(.05, _zoom), (input.LocalPosition.Y - _pointerStart.Y) / Math.Max(.05, _zoom)); if (_original is not null && _preview is not null) _preview = _interaction switch { Interaction.Move => _original.Transform with { X = _original.Transform.X + delta.X, Y = _original.Transform.Y + delta.Y }, Interaction.Resize => _original.Transform with { Width = Math.Max(12, _original.Transform.Width + delta.X), Height = Math.Max(12, _original.Transform.Height + delta.Y) }, Interaction.Rotate => _original.Transform with { RotationDegrees = RotationFor(_original.Transform, input.LocalPosition) }, _ => _preview }; else if (_interaction == Interaction.Pan) { _offset = new HavenPoint(_offset.X + input.LocalPosition.X - _pointerStart.X, _offset.Y + input.LocalPosition.Y - _pointerStart.Y); _pointerStart = input.LocalPosition; } Invalidate(); return true; }
    public bool PointerReleased(HavenPointerInput input) { if (_session is null) return false; if (_original is not null && _preview is not null && _interaction is Interaction.Move or Interaction.Resize or Interaction.Rotate) { var operation = _interaction == Interaction.Move ? "move" : _interaction == Interaction.Resize ? "resize" : "rotate"; _session.CommitObjectTransform(_original.Id, _preview, operation); } _interaction = Interaction.None; _original = null; _preview = null; Invalidate(); return true; }
    public bool PointerWheel(HavenPoint localPosition, double deltaX, double deltaY) { if (_session is null || Math.Abs(deltaY) < .001) return false; EnsureFit(); var before = ToBoard(localPosition); _zoom = Math.Clamp(_zoom * (deltaY < 0 ? 1.1 : .9), .05, 8); _offset = new HavenPoint(localPosition.X - before.X * _zoom, localPosition.Y - before.Y * _zoom); Invalidate(); return true; }
    public void Draw(HavenDrawingContext context, double opacity) { if (_session is null || Bounds.Width <= 2 || Bounds.Height <= 2) return; EnsureFit(); context.Add(new HavenFillRoundedRectCommand(Bounds, new HavenTokenBrush("SurfaceRaised"), 16, opacity)); var project = _session.Project; var canvas = ToScreen(new ImagineTransform(0, 0, project.CanvasWidth, project.CanvasHeight)); context.Add(new HavenFillRoundedRectCommand(canvas, new HavenSolidBrush(255, 255, 255, 255), 4, opacity)); context.Add(new HavenStrokeRoundedRectCommand(canvas, new HavenPen(new HavenTokenBrush("Border"), 1), 4, opacity)); foreach (var item in project.Objects.Where(item => item.IsVisible).OrderBy(item => item.ZIndex)) DrawObject(context, item, opacity); DrawSemanticBounds(context, opacity); if (SelectedObject() is { } selected) DrawSelection(context, selected, opacity); }
