    private ImagineEditableObject? SelectedObject() => _session?.Project.Selection is { Kind: ImagineSelectionKind.Object, TargetId: Guid id } ? _session.Project.Objects.FirstOrDefault(item => item.Id == id) : null; private void EnsureFit() { if (!_fitPending || _session is null || Bounds.Width <= 2 || Bounds.Height <= 2) return; var project = _session.Project; _zoom = Math.Clamp(Math.Min((Bounds.Width - 56) / project.CanvasWidth, (Bounds.Height - 56) / project.CanvasHeight), .05, 4); _offset = new HavenPoint((Bounds.Width - project.CanvasWidth * _zoom) / 2, (Bounds.Height - project.CanvasHeight * _zoom) / 2); _fitPending = false; } private HavenPoint ToBoard(HavenPoint local) => new((local.X - _offset.X) / Math.Max(.05, _zoom), (local.Y - _offset.Y) / Math.Max(.05, _zoom)); private HavenRect ToScreen(ImagineTransform value) => new(Bounds.X + _offset.X + value.X * _zoom, Bounds.Y + _offset.Y + value.Y * _zoom, value.Width * _zoom, value.Height * _zoom);
