    private static HavenBrush Brush(string value) { if (value is not { Length: 7 } || value[0] != '#' || !value.Skip(1).All(Uri.IsHexDigit)) return new HavenSolidBrush(255, 17, 17, 17); return new HavenSolidBrush(255, byte.Parse(value.AsSpan(1, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture), byte.Parse(value.AsSpan(3, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture), byte.Parse(value.AsSpan(5, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture)); } private void OnSessionChanged(object? sender, EventArgs e) => Invalidate(); public void Dispose() { if (_session is not null) _session.Changed -= OnSessionChanged; }
